                    "reason": {
                        "type": "string"
                    }
                }
            }
        },
        "safe_next_actions": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "kill_switch_status": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "enabled",
                "last_triggered_at",
                "command"
            ],
            "properties": {
                "enabled": {
                    "type": "boolean"
                },
                "last_triggered_at": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "command": {
                    "type": "string"
                }
            }
        }
    }
}

